import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';
import { useSystemBannerContext } from '../SystemBannerContext';
import { BANNER_ICON_ID } from '../constants';
import type { ComponentWithChildren } from '../types';

const SystemBannerIcon = ({
  children,
  dataTrackTag = 'system_banner_icon',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => {
  const { showIcon, iconInTitle } = useSystemBannerContext();

  return showIcon ? (
    <Container
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      as="span"
      style={iconInTitle ? { verticalAlign: 'bottom' } : undefined}
      flexShrink={iconInTitle ? undefined : 0}
      paddingRight="2"
      display="inlineFlex"
      height="24px"
      alignItems="center"
    >
      {children}
    </Container>
  ) : null;
};

SystemBannerIcon.displayName = 'SystemBannerIcon';
SystemBannerIcon.id = BANNER_ICON_ID;

export default SystemBannerIcon;
