import { createContext, useContext, type ReactNode } from 'react';
import type { SystemBannerProps } from '../types';

interface SystemBannerContextType {
    variant: SystemBannerProps['variant'];
    setDismissed: (value: boolean) => void;
    iconInTitle: boolean;
    showIcon: SystemBannerProps['showIcon'];
    bannerIcon: ReactNode;
}

export const SystemBannerContext = createContext<SystemBannerContextType>({} as SystemBannerContextType);

export const useSystemBannerContext = () => {
    const context = useContext(SystemBannerContext);
    if (context === undefined) {
        throw new Error('useSystemBannerContext must be used within a SystemBannerContextProvider');
    }
    return context;
};
