import React, { useState } from 'react';
import { findChildByType, filterChildrenByType } from '@fiverr-private/ui_utils';
import { Container, Stack, Section } from '@fiverr-private/layout_components';
import type { SystemBannerProps } from './types';
import { DISMISS_BUTTON_ID, BUTTON_ID, TEXT_ID, TITLE_ID, VARIANTS_CONFIG, BANNER_ICON_ID } from './constants';
import { SystemBannerContext } from './SystemBannerContext';
import SystemBannerIcon from './SystemBannerIcon';

const SystemBanner = ({
  variant,
  children,
  showIcon = true,
  dataTrackTag = 'system_banner',
  ...restProps
}: SystemBannerProps) => {
  const [dismissed, setDismissed] = useState(false);
  const title = findChildByType(children, TITLE_ID);
  const text = findChildByType(children, TEXT_ID);
  const buttons = filterChildrenByType(children, BUTTON_ID);
  const hasButtons = buttons.length > 0;
  const dismissButton = findChildByType(children, DISMISS_BUTTON_ID);
  const bannerIcon = findChildByType(children, BANNER_ICON_ID);
  const alignTextsToLeft = hasButtons || (title && text);

  const { Icon, backgroundColor } = VARIANTS_CONFIG[variant];

  if (dismissed) {
    return null;
  }

  const currentBannerIcon = bannerIcon || (
    <SystemBannerIcon>
      <Icon />
    </SystemBannerIcon>
  );

  return (
    <SystemBannerContext.Provider
      value={{ variant, setDismissed, iconInTitle: !alignTextsToLeft, showIcon, bannerIcon: currentBannerIcon }}
    >
      <Section backgroundColor={backgroundColor} fullWidth>
        <Container
          display="flex"
          justifyContent={hasButtons ? 'spaceBetween' : { sm: 'center' }}
          direction={hasButtons ? { default: 'column', sm: 'row' } : undefined}
          alignItems={{ sm: 'center' }}
          color="bodyPrimary"
          role="banner"
          paddingTop="4"
          paddingBottom="4"
          centered
          {...restProps}
          dataTrackTag={dataTrackTag}
        >
          <Container
            display="flex"
            justifyContent={alignTextsToLeft ? undefined : 'center'}
            marginLeft={dismissButton ? 'auto' : undefined}
          >
            <Stack gap="0">
              {alignTextsToLeft ? (
                <>
                  {currentBannerIcon}
                  <Container>
                    {title}
                    {text}
                  </Container>
                </>
              ) : (
                <Container display="flex">
                  {title}
                  {text}
                </Container>
              )}
            </Stack>
          </Container>
          {hasButtons && (
            <Container
              display="flex"
              marginTop={{ default: '4', sm: '0' }}
              paddingLeft={{ default: '0', sm: '4' }}
              flexShrink={0}
              gap="4"
              alignItems="center"
              alignSelf={{ default: 'flexEnd', sm: 'center' }}
            >
              {buttons}
            </Container>
          )}
          {Boolean(dismissButton) && (
            <Container alignSelf={{ default: 'flexStart', sm: 'center' }} paddingLeft="4" marginLeft="auto">
              {dismissButton}
            </Container>
          )}
        </Container>
      </Section>
    </SystemBannerContext.Provider>
  );
};

SystemBanner.displayName = 'SystemBanner';

export default SystemBanner;
