import React from 'react';
import { Text } from '@fiverr-private/typography';
import { type Types } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { TEXT_ID } from '../constants';

const SystemBannerText = ({
  children,
  dataTrackTag = 'system_banner_text',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => (
  <Text dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} color="inherit">
    {children}
  </Text>
);

SystemBannerText.id = TEXT_ID;
SystemBannerText.displayName = 'SystemBannerText';

export default SystemBannerText;
