import React from 'react';
import { Button, TextButton } from '@fiverr-private/button';
import type { SystemBannerButtonProps } from '../types';
import { BUTTON_ID } from '../constants';

const SystemBannerButton = ({
  children,
  intent = 'primary',
  onClick,
  href,
  dataTrackTag = 'system_banner_button',
  dataTrackValue,
}: SystemBannerButtonProps) => {
  const buttonProps = {
    href,
    target: href ? '_blank' : undefined,
    onClick,
    dataTrackTag,
    dataTrackValue,
  };

  if (intent === 'secondary') {
    return <TextButton {...buttonProps}>{children}</TextButton>;
  }

  return (
    <Button {...buttonProps} size="lg">
      {children}
    </Button>
  );
};

SystemBannerButton.id = BUTTON_ID;
SystemBannerButton.displayName = 'SystemBannerButton';

export default SystemBannerButton;
