import React from 'react';
import { TimesButton } from '@fiverr-private/button';
import { useSystemBannerContext } from '../SystemBannerContext';
import type { SystemBannerDismissButtonProps } from '../types';
import { DISMISS_BUTTON_ID } from '../constants';

const SystemBannerDismissButton = ({
  onClick,
  dataTrackTag = 'system_banner_dismiss_button',
  dataTrackValue,
}: SystemBannerDismissButtonProps) => {
  const { setDismissed } = useSystemBannerContext();

  return (
    <TimesButton
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      size="sm"
      onClick={(e) => {
        setDismissed(true);
        onClick?.(e);
      }}
    />
  );
};

SystemBannerDismissButton.displayName = 'SystemBannerDismissButton';
SystemBannerDismissButton.id = DISMISS_BUTTON_ID;

export default SystemBannerDismissButton;
