import React from 'react';
import { Text } from '@fiverr-private/typography';
import { type Types } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { TITLE_ID } from '../constants';
import { useSystemBannerContext } from '../SystemBannerContext';

const SystemBannerTitle = ({
  children,
  dataTrackTag = 'system_banner_title',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => {
  const { iconInTitle, bannerIcon } = useSystemBannerContext();
  return (
    <Text
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      fontWeight="semibold"
      color="inherit"
      textAlign={iconInTitle ? 'center' : undefined}
    >
      {iconInTitle ? bannerIcon : null}
      {children}
    </Text>
  );
};

SystemBannerTitle.id = TITLE_ID;
SystemBannerTitle.displayName = 'SystemBannerTitle';

export default SystemBannerTitle;
